// FUNCTION: BFME2 0x001A1860 size=64 name=?Notify_Added@ParticleEmitterClass@@UAEXPAVSceneClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Notify_Added(SceneClass *scene)
{
	RenderObjClass::Notify_Added(scene);
	scene->Register(this,SceneClass::ON_FRAME_UPDATE);

	if (FirstTime == false) {
		Active = true;
	}
	IsInScene = true;
}

// FUNCTION: BFME2 0x001A18A0 size=45 name=?Notify_Removed@ParticleEmitterClass@@UAEXPAVSceneClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Notify_Removed(SceneClass *scene)
{
	scene->Unregister(this,SceneClass::ON_FRAME_UPDATE);
	RenderObjClass::Notify_Removed(scene);
	Active = false;
	IsInScene = false;
}

// FUNCTION: BFME2 0x001A18D0 size=152 name=?Scale@ParticleEmitterClass@@UAEXM@Z evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Scale(float scale)
{
	// Scale all velosity and position parameters
	if (PosRand) PosRand->Scale(scale);
	BaseVel *= scale;
	if (VelRand) VelRand->Scale(scale);
	OutwardVel *= scale;

	// Scale sizes of all particles
	Buffer->Scale(scale);
}

void ParticleEmitterClass::Restart()
{
	// calling Start will cause all internal counters to reset
	Start();
}

// FUNCTION: BFME2 0x001A1970 size=266 name=?On_Frame_Update@ParticleEmitterClass@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::On_Frame_Update()
{
	if (Active && !IsComplete) {
		if (FirstTime) {
			// The particle buffer doesn't have a valid Scene yet - the emitter finds out what scene it belongs to
			// and then adds the particle buffer to it.
			if ( BufferSceneNeeded ) {
				if (Is_In_Scene()) {
					Buffer->Add(Scene);
					BufferSceneNeeded = false;
				} else {
					return;
				}
			}

			BufferSceneNeeded = false;

			// Initialize previous transform:
			PrevQ = Build_Quaternion(Get_Transform());
			{ const Matrix3D &tm = Get_Transform(); PrevOrig = Vector3(tm[0][3], tm[1][3], tm[2][3]); }

			FirstTime = false;
		}
	}

	if (Is_Complete()) {
		if (Is_In_Scene() && Is_Remove_On_Complete_Enabled()) {
			Scene->Register(this,SceneClass::RELEASE);
		}
	}
}

// FUNCTION: BFME2 0x001A1A80 size=149 name=?Reset@ParticleEmitterClass@@QAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Reset()
{
	// Note:  This flag needs to be set first thing, otherwise getting the transform will result in an
	// 'update_x' call which in turn will cause the Update_Visibilty function to call Start().
	Active = true;

	// Initialize previous transform:
	PrevQ = Build_Quaternion(Get_Transform());
	{ const Matrix3D &tm = Get_Transform(); PrevOrig = Vector3(tm[0][3], tm[1][3], tm[2][3]); }

	// Reset the number of particles to emit
	ParticlesLeft = MaxParticles;
	EmitRemain = 0;
	IsComplete = false;
}

// FUNCTION: BFME2 0x001A1B20 size=176 name=?Start@ParticleEmitterClass@@QAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Start()
{
	// Note:  This flag needs to be set first thing, otherwise getting the transform will result in an
	// 'update_x' call which in turn results in a 'Set_Animation_Hidden' call, which in turn will cause the
	// Update_Visibilty function to call this method.  And then... Stack Overflow!
	Active = true;

	// Initialize previous transform:
	PrevQ = Build_Quaternion(Get_Transform());
	{ const Matrix3D &tm = Get_Transform(); PrevOrig = Vector3(tm[0][3], tm[1][3], tm[2][3]); }

	// Reset the number of particles to emit (if necessary)
	if (IsComplete == true) {
		ParticlesLeft = MaxParticles;
		IsComplete = false;
	}

	// This is to keep track of particles so that the line segments can start and stop properly
	GroupID++;
	Buffer->Set_Current_GroupID(GroupID);
}

