// FUNCTION: BFME2 0x001A1DE0 size=1076 name=?Initialize_Particle@ParticleEmitterClass@@AAEXPAUNewParticleStruct@@IABVQuaternion@@ABVVector3@@@Z evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Initialize_Particle(NewParticleStruct *newpart, unsigned int timestamp, const Quaternion &quat, const Vector3 &orig)
{
	newpart->TimeStamp = timestamp;

	Vector3 rand_pos;
	if (PosRand) {
		PosRand->Get_Vector(rand_pos);
	} else {
		rand_pos.Set(0.0f, 0.0f, 0.0f);
	}

	Vector3 rot_pos;
	quat.Rotate_Vector(rand_pos, &rot_pos);
	newpart->Position = rot_pos + orig;

	Vector3 rand_vel;
	if (VelRand) {
		VelRand->Get_Vector(rand_vel);
	} else {
		rand_vel.Set(0.0f, 0.0f, 0.0f);
	}

	if (OutwardVel) {
		Vector3 outwards;
		float pos_l2 = rand_pos.Length2();
		if (pos_l2) {
			outwards = rand_pos * (OutwardVel * WWMath::Inv_Sqrt(pos_l2));
		} else {
			outwards.X = OutwardVel;
			outwards.Y = 0.0f;
			outwards.Z = 0.0f;
		}

		rand_vel += outwards;
	}

	rand_vel += BaseVel;

	Vector3 rot_vel;
	quat.Rotate_Vector(rand_vel, &rot_vel);
	newpart->Velocity = InheritedWorldSpaceEmitterVel + rot_vel;
	newpart->GroupID = GroupID;
}


