// FUNCTION: BFME2 0x001A2260 size=91 name=?Update_On_Visibilty@ParticleEmitterClass@@MAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Update_On_Visibilty()
{
	// Simply start or stop the emission based on the visibility state of the emitter.
	if (Is_Not_Hidden_At_All () && IsInvisible == false) {
		if (Is_Stopped () && IsInScene) {
			Start ();
			return;
		}
	}

	if (Is_Not_Hidden_At_All () == false || IsInvisible) {
		if (Is_Stopped () == false) {
			Stop ();
		}
	}
}

// FUNCTION: BFME2 0x001A22F0 size=869 name=?Create_From_Definition@ParticleEmitterClass@@SAPAV1@ABVParticleEmitterDefClass@@@Z evidence=N:ledger tier=B hypothesis:cohesion

// FUNCTION: BFME2 0x001A2670 size=760 name=?Create_New_Particles@ParticleEmitterClass@@AAEXABVQuaternion@@ABVVector3@@@Z evidence=N:ledger tier=B hypothesis:cohesion
unsigned int Greatest_Common_Divisor(unsigned int m, unsigned int n);

void ParticleEmitterClass::Create_New_Particles(const Quaternion &curr_quat, const Vector3 &curr_orig)
{
	Quaternion quat;
	Vector3 orig;

	unsigned int frametime = WW3D::Get_Frame_Time();
	if (frametime > 100 * EmitRate) {
		unsigned int buf_size = Buffer->Get_Buffer_Size();
		unsigned int gcd = Greatest_Common_Divisor(buf_size, BurstSize);
		unsigned int bursts = buf_size / gcd;
		unsigned int cycle_time = EmitRate * bursts;
		if (cycle_time > 1) {
			frametime = frametime % cycle_time;
		} else {
			frametime = 1;
		}
	}

	EmitRemain += frametime;

	float fl_frametime = (float)frametime;
	float alpha = 1 - ((float)EmitRemain / fl_frametime);
	float d_alpha = (float)EmitRate / fl_frametime;

	SlerpInfoStruct slerp_info;
	Slerp_Setup(PrevQ, curr_quat, &slerp_info);

	if (VelInheritFactor) {
		InheritedWorldSpaceEmitterVel = (curr_orig - PrevOrig) * (VelInheritFactor / fl_frametime);
	} else {
		InheritedWorldSpaceEmitterVel.Set(0.0, 0.0, 0.0);
	}

	for (; EmitRemain > EmitRate;) {
		EmitRemain -= EmitRate;

		alpha += d_alpha;
		quat = Cached_Slerp(PrevQ, curr_quat, alpha, &slerp_info);
		orig.X = PrevOrig.X + (curr_orig.X - PrevOrig.X) * alpha;
		orig.Y = PrevOrig.Y + (curr_orig.Y - PrevOrig.Y) * alpha;
		orig.Z = PrevOrig.Z + (curr_orig.Z - PrevOrig.Z) * alpha;

		unsigned int age = WW3D::Get_Sync_Time() - EmitRemain;
		unsigned int burst_size = BurstSize;
		if (OneTimeBurst) {
			burst_size = OneTimeBurstSize;
			OneTimeBurst = false;
		}

		if (ParticlesLeft > 0) {
			if (burst_size > (unsigned int)ParticlesLeft) {
				burst_size = (unsigned int)ParticlesLeft;
				ParticlesLeft = 0;
			} else {
				ParticlesLeft -= burst_size;
			}
			if (ParticlesLeft <= 0) {
				IsComplete = true;
			}
		}

		for (unsigned int i = 0; i < burst_size; i++) {
			Initialize_Particle(Buffer->Add_Uninitialized_New_Particle(), age, quat, orig);
		}

		if (IsComplete) break;
	}
}

// FUNCTION: BFME2 0x001A2970 size=388 name=?Emit@ParticleEmitterClass@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Emit(void)
{
	if (Active && !IsComplete) {
		Quaternion curr_quat;
		Vector3 curr_orig;

		curr_quat = Build_Quaternion(Get_Transform());
		curr_orig = Get_Transform().Get_Translation();

		Create_New_Particles(curr_quat, curr_orig);

		PrevQ = curr_quat;
		PrevOrig = curr_orig;
	} else {
		PrevQ = Build_Quaternion(Get_Transform());
		PrevOrig = Get_Transform().Get_Translation();
	}
}
