// FUNCTION: BFME2 0x001A30D0 size=26 name=?Save@ParticleEmitterClass@@QBE_NAAVChunkSaveClass@@@Z evidence=N:ledger tier=B hypothesis:Z
bool ParticleEmitterClass::Save(ChunkSaveClass &chunk_save) const
{
	// Assume error
	bool ret_val = false;

	ParticleEmitterDefClass *pdefinition = Build_Definition ();
	if (pdefinition != NULL) {
		ret_val = pdefinition->Save_W3D (chunk_save);
	}

	return ret_val;
}
